using System;
using System.IO;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace Warfront.Verification {
public static class FogVisibilityChecks {
 static void Check(bool v,string m){if(!v)throw new Exception(m);}
 [InitializeOnLoadMethod] static void Auto(){EditorApplication.delayCall+=()=>{var p=Path.Combine(Path.GetTempPath(),"warfront-fog.request");if(!File.Exists(p))return;if(EditorApplication.isPlayingOrWillChangePlaymode){Auto();return;}File.Delete(p);try{Run();File.WriteAllText(p+".result","PASS");}catch(Exception e){Debug.LogException(e);File.WriteAllText(p+".result",e.ToString());}};}
 [MenuItem("Warfront/Squad/Check Stable Fog Visibility")]
 public static void Run(){var root=new GameObject("Fog visibility checks");try{var scene=root.AddComponent<RetroFantasyScene>();scene.Initialize();var world=new MmoSnapshot{zone="squad",instance_id="fog-check"};scene.BeginField(world,Vector2.zero);scene.Actor("enemy:bot",1000,800,1,0,false,false,false,false);scene.SquadRole("enemy:bot","archer");scene.EndField();var actor=root.transform.Find("Encounter squad/enemy:bot");int id=actor.gameObject.GetInstanceID();var position=actor.localPosition;var animation=actor.GetComponent<Animation>();animation.Stop();var walk=animation["Walk"];walk.enabled=true;walk.weight=1;walk.speed=1;walk.time=.2f;animation.Sample();var torso=actor.Find("root/torso");var pose=torso.localRotation;var initialFade=actor.GetComponent("FogActorVisibility");if(initialFade!=null)initialFade.GetType().GetField("changed",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(initialFade,Time.unscaledTime-1f);scene.BeginField(world,Vector2.zero);scene.EndField();actor=root.transform.Find("Encounter squad/enemy:bot");Check(actor!=null,"Single missing snapshot immediately destroyed the enemy");Check(walk.enabled&&Mathf.Abs(walk.time-.2f)<.001f,"Missing enemy rewound its animation instead of freezing");animation.Sample();Check(Quaternion.Angle(pose,torso.localRotation)<.001f,"Hidden enemy changed its last bone pose");var fade=actor.GetComponent("FogActorVisibility");Check(fade!=null,"Enemy has no fog transition");var type=fade.GetType();float now=Time.unscaledTime;type.GetMethod("Sample").Invoke(fade,new object[]{now+.23f});float alpha=(float)type.GetProperty("Alpha").GetValue(fade);Check(alpha>0&&alpha<1,"Missing enemy does not fade gradually");Check(actor.localPosition==position,"Hidden enemy extrapolated new movement");scene.Actor("enemy:bot",1001,800,1,0,false,false,false,false);Check(actor.gameObject.GetInstanceID()==id,"Brief reappearance rebuilt enemy rig");type.GetMethod("Show").Invoke(fade,new object[]{now+.24f});type.GetMethod("Sample").Invoke(fade,new object[]{now+.5f});Check((float)type.GetProperty("Alpha").GetValue(fade)>.99f,"Reappearance did not restore opacity");type.GetMethod("Hide").Invoke(fade,new object[]{now-1f});scene.BeginField(world,Vector2.zero);scene.EndField();Check(root.transform.Find("Encounter squad/enemy:bot")==null,"Hidden enemy retention is unbounded");scene.BeginField(new MmoSnapshot{zone="frontier",instance_id="next"},Vector2.zero);Check(root.transform.Find("Encounter frontier/enemy:bot")==null,"Fog ghost leaked between fields");Debug.Log("FOG_VISIBILITY_CHECKS PASS: missing snapshot grace, opacity, frozen pose, rig reuse, bounded cleanup and field reset");}finally{UnityEngine.Object.DestroyImmediate(root);}}
}}


